const std::vector<std::string>& Fada::obterAparenciaCombate() const
{
    static std::vector<std::string> aparenciaReduzida;
    if (aparenciaReduzida.empty())
    {
        aparenciaReduzida = Aparencia::reduzirEscalaAscii(obterAparenciaRaca(), 3, 3);
    }
    return aparenciaReduzida;
}

// --- BESTIARIO E DROPS ---
InfoBestiario Fada::obterInfoBestiario() const {
    return {
        "Floresta", 
        "Superficie",
        "Fadas corrompidas pela energia negra da floresta.",
        "Elas costumavam guiar viajantes, agora os perdem.",
        {FabricaItens::obterNomeDeID(ItemID::PoMagico), FabricaItens::obterNomeDeID(ItemID::VarinhaCorroida), "Ouro"},
        3
    };
}

void Fada::realizarDrops(Personagem* inimigo, Personagem* jogadorAtual, std::vector<std::string>& itensObtidos, int& ouroTotal, int& xpTotal)
{
    Drops::relatarEProcessarXpOuro(jogadorAtual, 45, 20, ouroTotal, xpTotal);
    Drops::darEProcessarItem(jogadorAtual, ItemID::VarinhaCorroida, 1, itensObtidos, 65);
    Drops::darEProcessarItem(jogadorAtual, ItemID::PoMagico, GeradorAleatorio::obterInteiro(1, 6), itensObtidos);
}







